import type { Role } from '../app'
import type { FlowSchemaType, FlowValueType, FlowIOType, OutputsWithDotwalk } from './FlowTypes'
export interface FlowConfigProps {
    name: string
    description?: string
    runAs?: 'system' | 'user'
    runWithRoles?: (string | Role)[]
    flowPriority?: 'LOW' | 'MEDIUM' | 'HIGH'
    protection?: 'read' | ''
}
export interface SubflowProps {
    annotation?: string
    access?: 'public' | 'package_private'
    category?: string
}
type WithIO<I, O> = {
    inputs?: I
    outputs?: O
}

export type FlowVariableProps<V> = {
    flowVariables?: V
}

export type SubflowConfig<
    I extends Record<string, FlowValueType>,
    O extends Record<string, FlowValueType>,
    V extends Record<string, FlowValueType>,
> = Now.Internal.WithID<FlowConfigProps & SubflowProps> & WithIO<I, O> & FlowVariableProps<V>
/**
 * waitForCompletion is default input for subflow instances
 */
type RuntimeInputs<I> = I & { waitForCompletion?: boolean }
type Subflow<I, O> = {
    /**
     * Invokes the subflow.
     * @param id - An identifier for this specific instance of the subflow.
     * @param inputs - The input data for the subflow, conforming to the inferred input schema.
     * @returns The output data from the subflow, conforming to the inferred output schema.
     */
    <TInputs extends RuntimeInputs<I>>(id: Now.Internal.ExplicitKey | string, inputs: TInputs & RuntimeInputs<I>): O
    /** The schema definition for the subflow's inputs. */
    inputs: I
    /** The schema definition for the subflow's outputs. */
    outputs: O
}

export type SubflowBodyParams<I, O, V> = {
    inputs: I
    outputs: O
    flowVariables: V
}

export function SubflowDefinition<
    I extends Record<string, FlowValueType>,
    O extends Record<string, FlowValueType>,
    V extends Record<string, FlowValueType>,
>(
    _config: SubflowConfig<I, O, V>,
    _body?: (params: SubflowBodyParams<OutputsWithDotwalk<I>, FlowSchemaType<O>, OutputsWithDotwalk<V>>) => void
): Subflow<FlowIOType<I>, OutputsWithDotwalk<O>> {
    return undefined as unknown as Subflow<FlowIOType<I>, OutputsWithDotwalk<O>>
}

/**
 * Configuration object for Subflow instances
 */
type SubflowInstanceConfig = Now.Internal.WithID<{
    /** Optional annotation text for this specific subflow instance */
    annotation?: string
    uuid?: string
}>

/**
 * Helper type for subflow outputs when the subflow definition is not available (sys_id fallback).
 * Allows arbitrary property access for datapill references without TypeScript errors.
 * This is effectively `any` but typed in a way that allows dot notation property access.
 */
// biome-ignore lint/suspicious/noExplicitAny: This type intentionally allows arbitrary access for unresolved subflow outputs
type UnknownSubflowOutputs = any

/**
 * A generic function that represents an instance or invocation of a subflow.
 * Uses the configuration object format with $id and optional annotation.
 *
 * This function has two overloads:
 * 1. When a Subflow definition is provided: Returns typed outputs with known properties
 * 2. When a string (sys_id) is provided: Returns outputs with arbitrary property access support
 */

/**
 * Subflow instance with known Subflow definition - provides type-safe output property access
 * @template I - The type of the input parameters for the subflow.
 * @template O - The type of the output parameters for the subflow.
 * @template TInputs - The actual input type being passed, which must be assignable to RuntimeInputs<I>.
 * @param _subflow - The `Subflow` object (created by `SubflowDefinition`).
 * @param _config - Configuration object with $id and optional annotation.
 * @param _inputs - The input data provided to the subflow, including optional waitForCompletion.
 * @returns The expected output of the subflow, typed as `O` with known properties.
 */
// biome-ignore lint/suspicious/noRedeclare: TypeScript function overload signature (1 of 2)
export function Subflow<I, O, TInputs extends RuntimeInputs<I>>(
    _subflow: Subflow<I, O>,
    _config: SubflowInstanceConfig,
    _inputs: TInputs & RuntimeInputs<I>
): O & { type: 'subflow' }

/**
 * Subflow instance with sys_id fallback - allows arbitrary property access for datapill references
 * @param _subflow - A string sys_id when the subflow definition cannot be resolved.
 * @param _config - Configuration object with $id and optional annotation.
 * @param _inputs - The input data provided to the subflow (untyped).
 * @returns An object with arbitrary property access to support datapill references.
 */
// biome-ignore lint/suspicious/noRedeclare: TypeScript function overload signature (2 of 2)
export function Subflow(
    _subflow: string,
    _config: SubflowInstanceConfig,
    // biome-ignore lint/suspicious/noExplicitAny: Untyped inputs for fallback case
    _inputs: RuntimeInputs<Record<string, any>>
): { type: 'subflow' } & UnknownSubflowOutputs

/**
 * Implementation of Subflow function (handles both overloads)
 */
export function Subflow<I, O, TInputs extends RuntimeInputs<I>>(
    _subflow: Subflow<I, O> | string,
    _config: SubflowInstanceConfig,
    // biome-ignore lint/suspicious/noExplicitAny: Union type includes untyped fallback case
    _inputs: TInputs | any
): (O & { type: 'subflow' }) | UnknownSubflowOutputs {
    // biome-ignore lint/suspicious/noExplicitAny: Runtime returns undefined, type is for compile-time only
    return undefined as unknown as any
}
